// Get the CSV string from the data field
const csvString = items[0].json.data;

// Simple but robust CSV parser that handles commas in quoted fields
function parseCSV(csv) {
  const lines = [];
  let currentLine = [];
  let currentField = '';
  let insideQuotes = false;

  for (let i = 0; i < csv.length; i++) {
    const char = csv[i];
    const nextChar = csv[i + 1];

    if (char === '"') {
      if (insideQuotes && nextChar === '"') {
        // Escaped quote
        currentField += '"';
        i++; // Skip next quote
      } else {
        // Toggle quote state
        insideQuotes = !insideQuotes;
      }
    } else if (char === ',' && !insideQuotes) {
      // End of field
      currentLine.push(currentField);
      currentField = '';
    } else if (char === '\n' && !insideQuotes) {
      // End of line
      currentLine.push(currentField);
      lines.push(currentLine);
      currentLine = [];
      currentField = '';
    } else if (char === '\r') {
      // Skip carriage return
      continue;
    } else {
      currentField += char;
    }
  }

  // Add last field and line if any
  if (currentField || currentLine.length > 0) {
    currentLine.push(currentField);
    lines.push(currentLine);
  }

  return lines;
}

// Parse the CSV
const parsedLines = parseCSV(csvString);

// First line is headers
const headers = parsedLines[0].map(h => h.trim());

// Rest are data rows
const results = [];
for (let i = 1; i < parsedLines.length; i++) {
  const values = parsedLines[i];

  // Skip empty lines
  if (values.length === 0 || (values.length === 1 && !values[0])) {
    continue;
  }

  const row = {};
  headers.forEach((header, index) => {
    row[header] = values[index] ? values[index].trim() : '';
  });

  results.push(row);
}

return results.map(item => ({ json: item }));

