const results = [];

const csvItems = $('Extract from CSV').all();
const clItems = $('Cover letter').all();
const cvItems = $('Resume').all();

for (let i = 0; i < clItems.length; i++) {

  // --- 1. CLEANING THE COVER LETTER ---
  let rawLetter = clItems[i].json.text || "";
  let cleanLetter = rawLetter
      .split('\\n').join('\n')
      .replace(/[\[\]]/g, '');

  // --- 2. CLEANING THE CV (FOR OVERLEAF) ---
  let rawResume = cvItems[i].json.text || "";
  let formattedResume = rawResume.split('\\n').join('\n');

  // --- 3. GENERATING RTF CONTENT (For "Convert to RTF" Node) ---
  // RTF requires double backslashes for its own commands and \par for new lines




  results.push({
    json: {
      job_title: csvItems[i].json['title'] || csvItems[i].json['﻿title'], 
      job_url: csvItems[i].json.url,
      cover_letter: cleanLetter,   
      cv: formattedResume,         

    }
  });
}

return results;
